    return {"T": (1, 0), "F": (0, 1), "B": (1, 1), "N": (0, 0)}[v]

def _unpair(a, b):
    return {(1, 0): "T", (0, 1): "F", (1, 1): "B", (0, 0): "N"}[(a, b)]

