    print("negation:", {v: neg(v) for v in VALUES})
    for name, op in (("conj", conj), ("disj", disj)):
        print(f"\n{name}:")
        print("    " + "  ".join(VALUES))
        for x in VALUES:
            print(f"{x} | " + "  ".join(op(x, y) for y in VALUES))

