function audit_theory(truth, sent_neg, provable):
    coherent  = for all s: truth[sent_neg[s]] = neg(truth[s])
    sound     = for all s in provable: is_designated(truth[s])
    self_neg  = { s : sent_neg[s] = s }
    degree    = count of s with truth[s] = B
    explosion = exists provable glut g such that
                every sentence is designated
    return (coherent, sound, self_neg, degree, not explosion)

